mapper.select:
select t.id as task_id, t.name as task_name, coalesce(t.transfer_name, t.transfer_type, '') as transfer_name, greatest(t.uts, t.cts) as stats_time, t.status, (select count(*) from cc_task_contact c where c.task_id=t.id) as list_total, (select count(*) from cc_task_attempt a where a.task_id=t.id and a.call_id is not null) as dialed_count, (select count(*) from cc_task_attempt a where a.task_id=t.id and a.call_id is not null and a.result='answered') as answered_count, concat( round( case when (select count(*) from cc_task_attempt a where a.task_id=t.id and a.call_id is not null) > 0 then (select count(*) from cc_task_attempt a where a.task_id=t.id and a.call_id is not null and a.result='answered') * 100.0 / (select count(*) from cc_task_attempt a where a.task_id=t.id and a.call_id is not null) else 0 end, 1 ), '%' ) as answer_rate, (select count(*) from cc_task_contact c where c.task_id=t.id and c.call_status in ('pending','retry')) as pending_count, (select count(*) from cc_task_contact c where c.task_id=t.id and c.call_status in ('dialing','ringing','answered')) as in_call, cast(null as signed) as queue_count, (select count(distinct l.agent_id) from cc_agent_state_log l where l.company_id=t.company_id and l.state!='LOGOUT' and l.id=(select l2.id from cc_agent_state_log l2 where l2.company_id=l.company_id and l2.agent_id=l.agent_id order by l2.cts desc,l2.id desc limit 1)) as signed_in_agents, (select count(distinct l.agent_id) from cc_agent_state_log l where l.company_id=t.company_id and l.state='READY' and l.id=(select l2.id from cc_agent_state_log l2 where l2.company_id=l.company_id and l2.agent_id=l.agent_id order by l2.cts desc,l2.id desc limit 1)) as idle_agents, (select count(distinct l.agent_id) from cc_agent_state_log l where l.company_id=t.company_id and l.state in ('NOT_READY','OUT_CALL') and l.id=(select l2.id from cc_agent_state_log l2 where l2.company_id=l.company_id and l2.agent_id=l.agent_id order by l2.cts desc,l2.id desc limit 1)) as busy_agents, cast(null as signed) as after_call_agents, cast(null as signed) as abandoned_count from cc_task_config t
t.archived = 0 and t.company_id = #{companyId} and t.id = #{taskId} and t.status = #{status}
order by t.id desc
